Seguridad del balanceador de carga.ejemplo:
# Endurecimiento básico en NGINX como balanceador/proxy inverso
server {
    listen 443 ssl http2;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers on;
    client_header_timeout 10s;
    client_body_timeout 10s;
    proxy_set_header X-Forwarded-For $remote_addr; # Sobrescribe valor del cliente
    proxy_set_header Host $host;
}
